"use client";

import { useCallback, useId, useMemo, useRef, useState, type ReactNode } from "react";
import { useSearchParams } from "next/navigation";
import { cn } from "@/lib/utils";
import { chavesNaUrl, contarFiltrosAtivos, limpezaDosFiltros } from "@/lib/helpers/filtros-ativos";
import { useSetParams } from "@/lib/hooks/use-set-params";
import { useFiltrosPersistidos } from "@/lib/hooks/use-filtros-persistidos";
import { ViewsSalvasMenu } from "@/components/ui/views-salvas-menu";
import { useFiltrosPersistencia } from "@/components/ui/filtros-persistencia";
import type { FiltroConhecido } from "@/lib/helpers/views-salvas";
import type { FilterConfig, TabConfig } from "@/components/ui/filter-bar-config";
import { FilterControl } from "@/components/ui/filter-bar-controle";
import { ViewTabsPill } from "@/components/ui/filter-bar-abas";
import {
  BotaoPainelCompacto,
  LimparFiltros,
  LINHA_COMPACTA,
  PainelCompacto,
  ResumoCompacto,
  ROTULO_DO_PAINEL,
  rotuloAcimaNoPainel,
} from "@/components/ui/filter-bar-compacta";

export type {
  FilterConfig,
  FilterOption,
  FilterType,
  TabConfig,
} from "@/components/ui/filter-bar-config";
export { ViewTabsPill } from "@/components/ui/filter-bar-abas";

interface FilterBarProps {
  filters?: FilterConfig[];
  viewTabs?: TabConfig[];
  /** Nome do parâmetro de URL que guarda a visualização ativa. */
  viewParam?: string;
  /** Visualização usada quando a URL não traz `viewParam`. */
  defaultView?: string;
  /** Botões de contexto da tela (ex.: "Calendário editorial", "Gerar link"). Primeiro no cluster da direita. */
  contextActions?: ReactNode;
  /** Estrela de favorito — sempre por último à direita. */
  favorito?: ReactNode;
  /** @deprecated Use `contextActions`. Mantido como alias legado. */
  actions?: ReactNode;
  /**
   * Quando informado, ativa a persistência por usuário dos filtros desta tela
   * (capability persistencia-filtros-usuario): restaura o último filtro salvo na
   * abertura (se a URL não trouxer filtros) e salva alterações de forma
   * debounced. Sem `telaKey`, o comportamento permanece o atual. A leitura e a
   * gravação vêm do `FiltrosPersistenciaProvider`; sem ele, `telaKey` não grava
   * nada e o menu de views salvas não aparece.
   */
  telaKey?: string;
  /**
   * Opt-out da busca colapsável (padrão global = lupa que expande). Quando `true`, o
   * campo de busca fica sempre aberto no computador (768px ou mais). No celular, a
   * busca é sempre a lupa da barra compacta, que abre o campo na linha com um `X`
   * que limpa e fecha (v0.28.1).
   */
  buscaSempreAberta?: boolean;
  /**
   * Opt-out da linha única (padrão global = filtros e visões na mesma linha, com
   * rolagem horizontal dos filtros). Quando `true`, os filtros voltam a quebrar em
   * várias linhas (`flex-wrap`).
   */
  permitirQuebra?: boolean;
  /**
   * A tela recorta no navegador o que já carregou e o servidor não lê os filtros
   * (ex.: calendário do time). Com `true`, a barra escreve a URL pela History API
   * nativa (`history.replaceState`/`pushState`), que o Next sincroniza com
   * `useSearchParams` sem pedir a página de novo ao servidor. Vale para a
   * mudança de filtro, a restauração do filtro salvo e a aplicação de view.
   * Padrão: `router.replace`, como nas telas que filtram no servidor.
   */
  recorteLocal?: boolean;
  /**
   * Parâmetros que dizem onde a tela está, e não o recorte (ex.: `ano`, `mes` e
   * `dia` do calendário do time). Ficam fora das views salvas, não impedem a view
   * de aparecer como ativa e são mantidos ao aplicar uma view.
   */
  paramsDeNavegacao?: string[];
  /**
   * Barra compacta do celular: texto da linha, depois da aba escolhida (ex.:
   * "4 contas" ou "2 de 4 contas"). A barra não conhece a lista; a tela conta.
   */
  resumoCelular?: string;
  /**
   * Botão que fecha o painel de filtros do celular (ex.: "Ver 2 contas").
   * Padrão: "Fechar".
   */
  rotuloFecharPainel?: string;
}

/** Rolagem horizontal dos filtros no computador, com a barra de rolagem escondida. */
const ROLAGEM_NO_COMPUTADOR =
  "md:min-w-0 md:flex-1 md:overflow-x-auto md:[scrollbar-width:none] md:[-ms-overflow-style:none] md:[&::-webkit-scrollbar]:hidden";

// Classes de chip, menu e item de seleção: fonte única em `pilula.tsx`
// (padrão "Pílula de ação e de seleção", premium-design v0.10.0).
// A escrita na URL (com o reset de página) é o `useSetParams` de
// `@/lib/hooks/use-set-params` (change catalogo-componentes-premium-design, D7).

export function FilterBar({
  filters = [],
  viewTabs = [],
  viewParam = "view",
  defaultView,
  contextActions,
  favorito,
  actions,
  telaKey,
  buscaSempreAberta = false,
  permitirQuebra = false,
  recorteLocal = false,
  paramsDeNavegacao,
  resumoCelular,
  rotuloFecharPainel = "Fechar",
}: FilterBarProps) {
  // `actions` é alias legado de `contextActions` (zona de botões de contexto).
  const contexto = contextActions ?? actions;
  const searchParams = useSearchParams();

  const activeView = searchParams.get(viewParam) ?? defaultView ?? viewTabs[0]?.value;

  // Chaves de URL que contam como filtro (daterange e faixa expandem em
  // De/Ate; a busca com `aoBuscar` fica de fora). Base tanto da restauração
  // quanto do salvamento persistido. Regra pura em `filtros-ativos.ts`.
  const filterKeys = useMemo(() => chavesNaUrl(filters), [filters]);

  // Limpadores das buscas fora da URL (`aoBuscar`), chamados pelo "Limpar
  // filtros" junto com a limpeza da URL (change
  // catalogo-filterbar-faixa-busca-correcoes, D2).
  const limpadoresLocais = useRef(new Map<string, () => void>());
  const registrarLimpador = useCallback((key: string, limpar: () => void) => {
    const mapa = limpadoresLocais.current;
    mapa.set(key, limpar);
    return () => {
      if (mapa.get(key) === limpar) mapa.delete(key);
    };
  }, []);

  const { limpar: limparPersistido } = useFiltrosPersistidos({
    telaKey,
    filterKeys,
    local: recorteLocal,
  });

  // Views salvas só com tela identificada E persistência declarada: sem o
  // `FiltrosPersistenciaProvider`, a barra filtra pela URL e não mostra o menu
  // (change catalogo-componentes-premium-design, D6).
  const persistencia = useFiltrosPersistencia();
  const mostrarViews = telaKey != null && persistencia !== null;

  // Opções que a tela oferece HOJE, no formato mínimo de que o menu de views
  // precisa para avisar "filtro indisponível" quando uma view guarda um projeto
  // que foi excluído (capability views-salvas). Só filtros com lista fechada
  // entram: busca, data e toggle não têm opção para desaparecer.
  const filtrosConhecidos = useMemo<FiltroConhecido[]>(
    () =>
      filters
        .filter((f) => (f.type === "select" || f.type === "multiselect") && f.options?.length)
        .map((f) => ({
          key: f.key,
          label: f.label,
          multiplo: f.type === "multiselect",
          valores: (f.options ?? []).map((o) => o.value),
        })),
    [filters],
  );

  const setParams = useSetParams({ local: recorteLocal });

  // "Limpar filtros" só quando limpa mais do que a busca, que já tem o próprio
  // `X` (change busca-um-x-por-campo, D3); o mesmo número vai no botão de
  // filtros do celular. Regra pura em `filtros-ativos.ts`.
  const ativos = contarFiltrosAtivos(filters, (k) => searchParams.get(k));

  // Barra compacta do celular: a busca fica na linha; os outros filtros e as
  // abas, no painel que desce.
  const [painelAberto, setPainelAberto] = useState(false);
  const painelId = useId();
  const painelRef = useRef<HTMLDivElement>(null);
  const botaoPainelRef = useRef<HTMLButtonElement>(null);
  const buscas = filters.filter((f) => f.type === "search");
  const filtrosDoPainel = filters.filter((f) => f.type !== "search");
  const temPainel = filtrosDoPainel.length > 0 || viewTabs.length > 0;

  function fecharPainel() {
    setPainelAberto(false);
    botaoPainelRef.current?.focus();
  }

  function clearAll() {
    setParams(limpezaDosFiltros(filters));
    for (const limpar of limpadoresLocais.current.values()) limpar();
    // Limpar filtros também apaga o estado persistido da tela, para que a
    // próxima abertura não restaure o filtro anterior.
    limparPersistido();
  }

  const controle = (filter: FilterConfig) => (
    <FilterControl
      filter={filter}
      searchParams={searchParams}
      setParams={setParams}
      buscaColapsavel={!buscaSempreAberta}
      registrarLimpador={registrarLimpador}
    />
  );

  // No computador, a ordem fixa é filtros ► contexto ► abas ► favorito, numa
  // linha só (`order`, porque os invólucros do celular ficam `contents`). O
  // menu de views salvas abre a zona de contexto (capability views-salvas).
  return (
    <div
      className={cn(
        "mb-5 flex flex-col md:flex-row md:items-center md:gap-3",
        permitirQuebra && "md:flex-wrap",
      )}
    >
      <div className={LINHA_COMPACTA}>
        <ResumoCompacto
          aba={viewTabs.find((t) => t.value === activeView)?.label}
          resumo={resumoCelular}
        />
        {(mostrarViews || contexto != null) && (
          <div className="flex shrink-0 items-center gap-3 md:order-3">
            {mostrarViews && telaKey && (
              <ViewsSalvasMenu
                telaKey={telaKey}
                filtros={filtrosConhecidos}
                paramsDeNavegacao={paramsDeNavegacao}
                local={recorteLocal}
              />
            )}
            {contexto}
          </div>
        )}
        {favorito != null && (
          <div className="flex shrink-0 items-center md:order-5">{favorito}</div>
        )}
        {buscas.map((filter) => (
          <div
            key={filter.key}
            className="flex min-w-0 shrink-0 max-md:has-[[data-busca-aberta]]:flex-1 md:order-1"
          >
            {controle(filter)}
          </div>
        ))}
        {temPainel && (
          <BotaoPainelCompacto
            botaoRef={botaoPainelRef}
            aberto={painelAberto}
            painelId={painelId}
            ativos={ativos}
            comAbas={viewTabs.length > 0}
            onClick={() => setPainelAberto((a) => !a)}
            aoFechar={fecharPainel}
          />
        )}
      </div>

      <PainelCompacto
        id={painelId}
        painelRef={painelRef}
        aberto={painelAberto}
        aoFechar={fecharPainel}
        rotuloFechar={rotuloFecharPainel}
      >
        {viewTabs.length > 0 && (
          <div className="flex flex-col gap-3 px-4 py-3.5 md:contents">
            <span className={cn(ROTULO_DO_PAINEL, "md:hidden")}>Visão</span>
            <div className="md:order-4 md:shrink-0">
              <ViewTabsPill
                viewTabs={viewTabs}
                activeView={activeView}
                viewParam={viewParam}
                setParams={setParams}
                compacta
              />
            </div>
          </div>
        )}
        {/* Filtros: no celular, um por linha, com o rótulo acima; no computador,
            linha única com rolagem horizontal (os menus vêm em portal e não são
            cortados). Opt-out `permitirQuebra` → flex-wrap. */}
        <div
          className={cn(
            "relative flex flex-col gap-3 px-4 py-3.5 md:order-2 md:flex-1 md:flex-row md:items-center md:gap-[10px] md:p-0",
            viewTabs.length > 0 && "max-md:border-t max-md:border-[var(--premium-mist)]",
            filtrosDoPainel.length === 0 && "max-md:hidden",
            permitirQuebra ? "md:flex-wrap" : ROLAGEM_NO_COMPUTADOR,
          )}
        >
          <span className={cn(ROTULO_DO_PAINEL, "flex min-h-6 items-center md:hidden")}>
            Filtros
          </span>
          {filtrosDoPainel.map((filter) => (
            <div
              key={filter.key}
              className="flex flex-col gap-1.5 max-md:*:w-full md:contents max-md:[&>:last-child]:min-h-11"
            >
              {rotuloAcimaNoPainel(filter) && (
                <span aria-hidden className={cn(ROTULO_DO_PAINEL, "md:hidden")}>
                  {filter.label}
                </span>
              )}
              {controle(filter)}
            </div>
          ))}
          {/* Funil com x, não `X`: o `X` fica reservado ao limpar de um campo,
              e o funil diz "filtros" (change busca-um-x-por-campo, D3). */}
          {ativos > 0 && <LimparFiltros onClick={clearAll} />}
        </div>
      </PainelCompacto>
    </div>
  );
}

/**
 * Tipos e regras puras da `FilterBar`: a configuração de cada filtro e de cada
 * aba, e a busca e o limite das opções dos filtros de seleção.
 */
import type { useSearchParams } from "next/navigation";
import type { LucideIcon } from "lucide-react";

export type FilterType = "select" | "multiselect" | "daterange" | "toggle" | "search" | "faixa";

export interface FilterOption {
  value: string;
  label: string;
}

// Busca acento/caixa-insensível — mesmo padrão de multi-select.tsx / select.tsx.
const norm = (s: string) => s.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");

/** A partir deste tamanho a lista ganha campo de busca automaticamente. */
const BUSCA_A_PARTIR_DE = 8;

/**
 * Limite padrão de opções exibidas (sem termo) quando a busca está disponível e a
 * lista é longa — padrão global (capability filter-bar-busca-layout-global), no mesmo
 * espírito do filtro "Projeto" da Gestão de Demandas. `limiteVisivel` por filtro
 * sobrescreve; nunca corta quando não há busca (itens ficariam inacessíveis).
 */
const LIMITE_VISIVEL_PADRAO = 6;

export interface FilterConfig {
  /** Chave usada na URL (para `daterange` e `faixa` vira `<key>De` e `<key>Ate`). */
  key: string;
  label: string;
  type: FilterType;
  options?: FilterOption[];
  icon?: LucideIcon;
  /** Texto exibido quando nenhum valor está selecionado (tipos select). */
  placeholder?: string;
  /**
   * Força (ou oculta) o campo de busca nas opções (`select`/`multiselect`).
   * Default: automático — aparece quando há ao menos `BUSCA_A_PARTIR_DE` opções.
   */
  searchable?: boolean;
  /**
   * Limite de opções exibidas **enquanto não há termo de busca** (ex.: 5). Ao
   * digitar, a busca abrange a lista completa (não só as visíveis por padrão).
   */
  limiteVisivel?: number;
  /**
   * Chaves de URL que saem junto quando este filtro é limpo (`select` e
   * `multiselect`), na mesma escrita. Para filtros que só fazem sentido com
   * este preenchido (ex.: "Onde está" depende de "Responsável"), de modo que
   * não sobre parâmetro órfão na URL nem no filtro persistido.
   */
  limpaJunto?: string[];
  /**
   * Limites da `faixa` (filtro de faixa numérica, "de" e "até"). Obrigatórios
   * quando o tipo é `faixa`: o valor fora deles vai para o limite mais próximo.
   */
  min?: number;
  max?: number;
  /** Incremento dos campos da `faixa`. Padrão 1. */
  passo?: number;
  /**
   * Busca fora da URL (`search`): com a função, o termo fica só no estado do
   * componente e chega aqui com o mesmo atraso da busca pela URL, e `""` ao
   * limpar. Não vai para a URL, para os filtros persistidos nem para as views
   * salvas. Para buscas com dado pessoal (nome, e-mail). Pode mudar a cada
   * render: a barra a guarda em ref.
   */
  aoBuscar?: (termo: string) => void;
}

/** Atualizações de URL de um filtro, somando as chaves dependentes quando ele é limpo. */
export function comDependentes(
  filter: FilterConfig,
  valor: string | null,
): Record<string, string | null> {
  const updates: Record<string, string | null> = { [filter.key]: valor };
  if (valor === null) for (const k of filter.limpaJunto ?? []) updates[k] = null;
  return updates;
}

export function mostrarBuscaPara(filter: FilterConfig): boolean {
  return filter.searchable ?? (filter.options?.length ?? 0) >= BUSCA_A_PARTIR_DE;
}

/**
 * Limite efetivo de itens visíveis (sem termo). Usa `limiteVisivel` quando o filtro o
 * define; senão aplica `LIMITE_VISIVEL_PADRAO` **apenas quando a busca está
 * disponível** (do contrário os itens ocultos ficariam inacessíveis) e a lista é maior
 * que o limite. `null` = não cortar.
 */
function limiteEfetivo(filter: FilterConfig): number | null {
  if (filter.limiteVisivel != null) return filter.limiteVisivel;
  if (!mostrarBuscaPara(filter)) return null;
  const n = filter.options?.length ?? 0;
  return n > LIMITE_VISIVEL_PADRAO ? LIMITE_VISIVEL_PADRAO : null;
}

/**
 * Aplica busca/limite às opções de um filtro select/multiselect, preservando a
 * ordem fornecida pela tela (a FilterBar nunca reordena). Sem termo, corta no limite
 * efetivo; com termo, filtra a lista inteira.
 */
export function filtrarOpcoes(filter: FilterConfig, termo: string): FilterOption[] {
  const opcoes = filter.options ?? [];
  const t = norm(termo.trim());
  if (t) return opcoes.filter((o) => norm(o.label).includes(t));
  const lim = limiteEfetivo(filter);
  return lim != null ? opcoes.slice(0, lim) : opcoes;
}

export interface TabConfig {
  value: string;
  label: string;
  icon?: LucideIcon;
  /** Contagem exibida ao lado do rótulo (ex.: abas "Todas 128" da Tabela). */
  count?: number;
}

/** Leitura dos parâmetros da URL, como o `useSearchParams` devolve. */
export type ParamsDaUrl = ReturnType<typeof useSearchParams>;

/** Escrita na URL: `null` remove a chave. */
export type EscreverParams = (updates: Record<string, string | null>) => void;

/** Props dos controles de um filtro com menu (seleção e faixa). */
export interface PropsControleFiltro {
  filter: FilterConfig;
  searchParams: ParamsDaUrl;
  setParams: EscreverParams;
}

"use client";

import { useEffect, useRef, useState } from "react";
import { Check } from "lucide-react";
import { cn } from "@/lib/utils";
import { navegarComTransicao } from "@/lib/view-transition";
import type { EscreverParams, TabConfig } from "@/components/ui/filter-bar-config";

/** A partir de quantas abas o painel da barra compacta as mostra em lista. */
const ABAS_EM_LISTA_A_PARTIR_DE = 4;

/** No painel da barra compacta, as abas vão em lista a partir de quatro. */
export function abasEmLista(viewTabs: readonly TabConfig[]): boolean {
  return viewTabs.length >= ABAS_EM_LISTA_A_PARTIR_DE;
}

/** Abas em lista no celular: caixa com borda, uma aba por linha. */
const LISTA_NO_CELULAR =
  "max-md:flex-col max-md:gap-0 max-md:overflow-hidden max-md:border max-md:border-[var(--premium-mist)] max-md:bg-[var(--premium-white)] max-md:p-0";

/** Uma aba da lista no celular: linha de 44px, a escolhida com a borda amarela à esquerda. */
const ITEM_DA_LISTA_NO_CELULAR =
  "max-md:min-h-11 max-md:rounded-none max-md:border-l-[3px] max-md:border-transparent max-md:px-3.5 max-md:text-left max-md:text-[var(--premium-ink)] max-md:not-first:border-t max-md:not-first:border-t-[var(--premium-bone)] max-md:aria-pressed:border-l-[var(--yellow)] max-md:aria-pressed:bg-[var(--premium-bone)]";

/**
 * Grupo de tabs de visão com pílula deslizante (CSS, medida por ref — sem
 * `layoutId`/`domMax`) e troca de conteúdo via View Transitions quando disponível
 * (change animacoes-graficos-abas-transicoes).
 *
 * A `FilterBar` renderiza um grupo (o `viewParam` da tela) no cluster da direita.
 * Exportado para telas que precisam de um **segundo** grupo de abas em outro
 * lugar do layout e em outro param — caso das abas "Todas/Para hoje/Atrasadas"
 * (`?aba=`) da visão Tabela de demandas, que ficam acima da tabela. Reusar este
 * componente (com `useSetParams`) mantém uma só implementação de estado de aba em
 * searchParam, com o mesmo visual e o mesmo reset de página.
 *
 * `compacta` (a `FilterBar` passa no painel da barra compacta, premium-design
 * v0.28.0): no celular, o grupo ocupa a largura do painel, em controle
 * segmentado até três abas e em lista, uma por linha e com o visto na
 * escolhida, a partir de quatro. No computador, nada muda.
 */
export function ViewTabsPill({
  viewTabs,
  activeView,
  viewParam,
  setParams,
  compacta = false,
}: {
  viewTabs: TabConfig[];
  activeView: string | undefined;
  viewParam: string;
  setParams: EscreverParams;
  compacta?: boolean;
}) {
  const listRef = useRef<HTMLDivElement>(null);
  const btnRefs = useRef<Record<string, HTMLButtonElement | null>>({});
  const [ind, setInd] = useState<{ left: number; width: number } | null>(null);

  useEffect(() => {
    const btn = activeView ? btnRefs.current[activeView] : null;
    const list = listRef.current;
    if (!btn || !list) return;
    const atualizar = () => setInd({ left: btn.offsetLeft, width: btn.offsetWidth });
    atualizar();
    const ro = new ResizeObserver(atualizar);
    ro.observe(list);
    return () => ro.disconnect();
  }, [activeView, viewTabs.length]);

  const emLista = compacta && abasEmLista(viewTabs);

  return (
    <div
      ref={listRef}
      className={cn(
        "relative flex gap-1 rounded-[var(--r-md)] bg-[var(--premium-bone)] p-1",
        compacta && !emLista && "max-md:grid max-md:auto-cols-fr max-md:grid-flow-col",
        emLista && LISTA_NO_CELULAR,
      )}
    >
      {ind && (
        <span
          aria-hidden
          className={cn(
            "absolute top-1 bottom-1 rounded-[var(--r-sm)] bg-[var(--premium-white)] shadow-[var(--sh-sm)] transition-[left,width] duration-200 ease-[var(--ease)] motion-reduce:transition-none",
            emLista && "max-md:hidden",
          )}
          style={{ left: ind.left, width: ind.width }}
        />
      )}
      {viewTabs.map((tab) => {
        const active = tab.value === activeView;
        const Icon = tab.icon;
        return (
          <button
            key={tab.value}
            ref={(el) => {
              btnRefs.current[tab.value] = el;
            }}
            onClick={() => navegarComTransicao(() => setParams({ [viewParam]: tab.value }))}
            // Anuncia a opção ativa ao leitor de tela (change qg-cliente, spec
            // qg-cliente-lista): o destaque visual sozinho não basta.
            aria-pressed={active}
            className={cn(
              "relative z-[1] flex cursor-pointer items-center gap-[7px] rounded-[var(--r-sm)] px-4 py-2 text-[13px] font-medium transition-colors",
              active ? "font-bold text-[var(--premium-ink)]" : "text-[var(--premium-steel)]",
              compacta && !emLista && "max-md:justify-center",
              emLista && ITEM_DA_LISTA_NO_CELULAR,
            )}
          >
            {emLista && (
              <Check
                size={16}
                aria-hidden
                className={cn("shrink-0 md:hidden", !active && "invisible")}
              />
            )}
            {Icon && <Icon size={15} />} {tab.label}
            {tab.count != null && (
              <span
                className={cn(
                  "text-[11px] text-[var(--premium-gray)]",
                  emLista && "max-md:ml-auto",
                )}
              >
                {tab.count}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { buscaLocal, chavesDaFaixa } from "@/lib/helpers/filtros-ativos";
import { DatePicker } from "@/components/ui/date-picker";
import { chipActive, chipBase, chipIdle, chipOn } from "@/components/ui/pilula";
import type { EscreverParams, FilterConfig, ParamsDaUrl } from "@/components/ui/filter-bar-config";
import { BuscaLocalControl, SearchFilterControl } from "@/components/ui/filter-bar-busca";
import { FaixaFilterControl } from "@/components/ui/filter-bar-faixa";
import { MultiSelectControl, SingleSelectControl } from "@/components/ui/filter-bar-selecao";

/** Um filtro da barra: escolhe o controle pelo tipo. */
export function FilterControl({
  filter,
  searchParams,
  setParams,
  buscaColapsavel,
  registrarLimpador,
}: {
  filter: FilterConfig;
  searchParams: ParamsDaUrl;
  setParams: EscreverParams;
  buscaColapsavel: boolean;
  registrarLimpador: (key: string, limpar: () => void) => () => void;
}) {
  const Icon = filter.icon;

  if (buscaLocal(filter) && filter.aoBuscar) {
    return (
      <BuscaLocalControl
        filter={filter}
        aoBuscar={filter.aoBuscar}
        colapsavel={buscaColapsavel}
        registrarLimpador={registrarLimpador}
      />
    );
  }

  if (filter.type === "search") {
    return (
      <SearchFilterControl
        filter={filter}
        searchParams={searchParams}
        setParams={setParams}
        colapsavel={buscaColapsavel}
      />
    );
  }

  if (filter.type === "toggle") {
    const active = searchParams.get(filter.key) === "1";
    return (
      <button
        onClick={() => setParams({ [filter.key]: active ? null : "1" })}
        aria-pressed={active}
        className={cn(chipBase, active ? chipOn : chipIdle)}
      >
        {Icon && (
          <Icon
            size={14}
            className={active ? "text-[var(--yellow)]" : "text-[var(--premium-gray)]"}
          />
        )}
        {filter.label}
      </button>
    );
  }

  if (filter.type === "daterange") {
    const [chaveDe, chaveAte] = chavesDaFaixa(filter);
    const de = searchParams.get(chaveDe) ?? "";
    const ate = searchParams.get(chaveAte) ?? "";
    const active = Boolean(de || ate);
    return (
      <div className={cn(chipBase, active ? chipActive : chipIdle, "cursor-default")}>
        {Icon && <Icon size={14} className="text-[var(--premium-gray)]" />}
        <span className="text-[var(--premium-gray)]">{filter.label}</span>
        <DatePicker
          variant="inline"
          value={de}
          max={ate || undefined}
          onChange={(e) => setParams({ [chaveDe]: e.target.value || null })}
          placeholder="Início"
          ariaLabel={`${filter.label}: data inicial`}
        />
        <span className="text-[var(--premium-gray)]">–</span>
        <DatePicker
          variant="inline"
          value={ate}
          min={de || undefined}
          onChange={(e) => setParams({ [chaveAte]: e.target.value || null })}
          placeholder="Fim"
          ariaLabel={`${filter.label}: data final`}
        />
      </div>
    );
  }

  if (filter.type === "faixa") {
    return <FaixaFilterControl filter={filter} searchParams={searchParams} setParams={setParams} />;
  }

  if (filter.type === "multiselect") {
    return <MultiSelectControl filter={filter} searchParams={searchParams} setParams={setParams} />;
  }

  // select (padrão) — pílula com dropdown custom (mesmo painel do multiselect).
  return <SingleSelectControl filter={filter} searchParams={searchParams} setParams={setParams} />;
}

"use client";

import { useEffect, useRef, useState, useTransition } from "react";
import { Search, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { campoAdotaUrl } from "@/lib/helpers/busca-filtro-url";
import { useBuscaLocal } from "@/lib/hooks/use-busca-local";
import { chipActive, chipBase, chipIdle } from "@/components/ui/pilula";
import type { EscreverParams, FilterConfig, ParamsDaUrl } from "@/components/ui/filter-bar-config";

// Filtro de busca por palavra-chave: input textual persistido na URL
// (`<key>`), com debounce para não thrashar o histórico enquanto digita. Tokens
// semânticos, foco visível e contraste AA em claro/escuro.
export function SearchFilterControl({
  filter,
  searchParams,
  setParams,
  colapsavel,
}: {
  filter: FilterConfig;
  searchParams: ParamsDaUrl;
  setParams: EscreverParams;
  colapsavel: boolean;
}) {
  const urlValue = searchParams.get(filter.key) ?? "";
  const [valor, setValor] = useState(urlValue);
  const [urlAnterior, setUrlAnterior] = useState(urlValue);
  // Escrita do campo a caminho da URL: o debounce correndo (`digitando`) ou a
  // navegação disparada por ele ainda sem confirmar (`navegando`). Estado, não
  // ref, porque é lido durante o render.
  const [digitando, setDigitando] = useState(false);
  const [navegando, startNavegacao] = useTransition();
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Reflete mudanças externas da URL (ex.: "Limpar filtros") no campo, sem
  // efeito: padrão "ajuste de estado durante o render" do React (rastreia o
  // último valor da URL via estado, não ref). Só quando não há escrita do campo
  // a caminho: a URL muda quando a resposta do servidor chega, e a resposta
  // atrasada de uma escrita anterior traz o termo antigo, que apagaria o que
  // acabou de ser digitado (change filter-bar-busca-digitacao-estavel).
  if (campoAdotaUrl({ urlValue, urlAnterior, escritaPendente: digitando || navegando })) {
    setUrlAnterior(urlValue);
    setValor(urlValue);
  }

  function onChange(v: string) {
    setValor(v);
    setDigitando(true);
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => {
      setDigitando(false);
      // Na transição, `navegando` fica verdadeiro até a URL confirmar.
      startNavegacao(() => setParams({ [filter.key]: v.trim() || null }));
    }, 300);
  }

  function limpar() {
    setValor("");
    setDigitando(false);
    if (timer.current) clearTimeout(timer.current);
    startNavegacao(() => setParams({ [filter.key]: null }));
  }

  return (
    <ChipBusca
      filter={filter}
      valor={valor}
      onChange={onChange}
      onLimpar={limpar}
      colapsavel={colapsavel}
    />
  );
}

// Busca fora da URL (`aoBuscar`): o termo fica no estado do componente e chega
// à tela pela função, com o mesmo atraso (change
// catalogo-filterbar-faixa-busca-correcoes, D2). O limpador entra no registro
// da barra para o "Limpar filtros" esvaziar o campo e chamar `aoBuscar("")`.
export function BuscaLocalControl({
  filter,
  aoBuscar,
  colapsavel,
  registrarLimpador,
}: {
  filter: FilterConfig;
  aoBuscar: (termo: string) => void;
  colapsavel: boolean;
  registrarLimpador: (key: string, limpar: () => void) => () => void;
}) {
  const { valor, alterar, limpar } = useBuscaLocal({ aoBuscar });

  useEffect(() => registrarLimpador(filter.key, limpar), [registrarLimpador, filter.key, limpar]);

  return (
    <ChipBusca
      filter={filter}
      valor={valor}
      onChange={alterar}
      onLimpar={limpar}
      colapsavel={colapsavel}
    />
  );
}

// Chip da busca, o mesmo para a busca pela URL e para a busca fora dela: a
// lupa colapsável, o campo e o `X` de limpar.
//
// No celular (barra compacta, premium-design v0.28.0), o chip fica na linha da
// barra: fechado, é um botão de 44px com a lupa; aberto, ocupa a linha (menos o
// botão de filtros) e sempre tem um `X`, que limpa e fecha. `data-busca-aberta`
// avisa a linha para esconder o resumo enquanto a busca está aberta.
//
// `colapsavel={false}` (o `buscaSempreAberta` da barra) vale só no computador
// (v0.28.1): ali o campo fica sempre aberto, com a lupa só de enfeite; no
// celular, a busca continua a lupa da barra compacta. A troca é só por CSS
// (`md:`), sem medir a tela, para a primeira pintura já sair certa.
function ChipBusca({
  filter,
  valor,
  onChange,
  onLimpar,
  colapsavel,
}: {
  filter: FilterConfig;
  valor: string;
  onChange: (v: string) => void;
  onLimpar: () => void;
  colapsavel: boolean;
}) {
  const Icon = filter.icon ?? Search;
  const [expandido, setExpandido] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const chipRef = useRef<HTMLDivElement>(null);
  const lupaRef = useRef<HTMLButtonElement>(null);

  const active = valor.trim().length > 0;
  // Aberto (no celular, e no computador quando colapsável) quando expandido
  // manualmente ou com termo. Sem `colapsavel`, o computador mostra o campo sempre.
  const aberto = expandido || active;
  const fixoNoComputador = !colapsavel && !aberto;

  // Foca o input ao expandir (capability filter-bar-busca-layout-global).
  useEffect(() => {
    if (aberto && expandido) inputRef.current?.focus();
  }, [aberto, expandido]);

  function limpar() {
    onLimpar();
    setExpandido(false);
  }

  /** O `X` sem termo (só no celular) fecha e devolve o foco à lupa. */
  function fechar() {
    setExpandido(false);
    lupaRef.current?.focus();
  }

  // Um único elemento que cresce suavemente: a lupa fica sempre visível e o campo
  // anima a largura/opacidade de 0 → 200px ao abrir (capability
  // filter-bar-busca-layout-global). `overflow-hidden` esconde o campo recolhido.
  return (
    <div
      ref={chipRef}
      data-busca-aberta={aberto ? "" : undefined}
      className={cn(
        chipBase,
        active ? chipActive : chipIdle,
        "shrink-0 overflow-hidden max-md:h-11",
        aberto
          ? "cursor-text gap-2 max-md:min-w-0 max-md:flex-1 max-md:pr-0.5 max-md:focus-within:border-[var(--premium-ink)] max-md:focus-within:shadow-[0_0_0_2px_var(--yellow-50)]"
          : "cursor-pointer gap-0 max-md:w-11 max-md:justify-center max-md:rounded-[var(--r-md)] max-md:px-0",
        fixoNoComputador && "md:cursor-text md:gap-2",
      )}
      onClick={() => {
        if (!aberto) setExpandido(true);
      }}
    >
      <button
        ref={lupaRef}
        type="button"
        onClick={(e) => {
          if (!aberto) {
            e.stopPropagation();
            setExpandido(true);
          }
        }}
        aria-label={filter.label}
        aria-expanded={aberto}
        tabIndex={aberto ? -1 : 0}
        className={cn(
          "flex shrink-0 items-center justify-center focus-visible:rounded-full focus-visible:ring-2 focus-visible:ring-[var(--yellow-50)] focus-visible:outline-none",
          !colapsavel && "md:hidden",
        )}
      >
        <Icon size={18} className="text-[var(--premium-gray)]" />
      </button>
      {/* Sem `colapsavel`, no computador a lupa é só o ícone do campo aberto. */}
      {!colapsavel && (
        <Icon size={18} aria-hidden className="shrink-0 text-[var(--premium-gray)] max-md:hidden" />
      )}
      <input
        ref={inputRef}
        type="search"
        value={valor}
        onChange={(e) => onChange(e.target.value)}
        onBlur={(e) => {
          // O foco que vai para o `X` do próprio chip não recolhe o campo.
          if (!valor.trim() && !chipRef.current?.contains(e.relatedTarget)) setExpandido(false);
        }}
        onKeyDown={(e) => {
          if (e.key === "Escape" && !valor.trim()) setExpandido(false);
        }}
        placeholder={filter.placeholder ?? filter.label}
        aria-label={filter.label}
        aria-hidden={colapsavel ? !aberto : undefined}
        tabIndex={aberto || !colapsavel ? 0 : -1}
        style={{ width: aberto ? 200 : 0, opacity: aberto ? 1 : 0 }}
        className={cn(
          "bg-transparent text-[13px] text-[var(--premium-ink)] transition-[width,opacity] duration-200 ease-out placeholder:text-[var(--premium-gray)] focus:outline-none",
          // No celular, o foco aparece no chip inteiro, não num retângulo dentro dele.
          aberto && "max-md:w-auto! max-md:min-w-0 max-md:flex-1 max-md:focus-visible:shadow-none",
          // Fechado no celular, fora do Tab e do leitor de tela; aberto no computador.
          fixoNoComputador && "max-md:invisible md:w-[200px]! md:opacity-100!",
        )}
      />
      {/* O único controle de limpar do campo: o "x" nativo do type="search" é
          escondido pela regra base do globals.css (change busca-um-x-por-campo).
          Alvo de 24×24px (antes o ícone de 14px era o próprio alvo); o -mr
          devolve o respiro direito do chip. Limpar recolhe o chip, então o foco
          não volta ao campo, que some. */}
      {aberto && (
        <button
          type="button"
          onClick={active ? limpar : fechar}
          aria-label={active ? "Limpar busca" : "Fechar a busca"}
          className={cn(
            "-mr-[5px] flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-[var(--premium-gray)] hover:text-[var(--premium-ink)] focus-visible:ring-2 focus-visible:ring-[var(--yellow-50)] focus-visible:outline-none max-md:mr-0 max-md:size-10",
            // Sem termo, o `X` só fecha: existe só na barra compacta do celular.
            !active && "md:hidden",
          )}
        >
          <X size={14} />
        </button>
      )}
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState } from "react";
import {
  chavesDaFaixa,
  escritaDaFaixa,
  normalizarFaixa,
  resumoFaixa,
  rotuloFaixa,
  type LimitesFaixa,
} from "@/lib/helpers/filtros-ativos";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useDropdownPortal } from "@/components/ui/pilula";
import type { FilterConfig, PropsControleFiltro } from "@/components/ui/filter-bar-config";
import { GatilhoFiltro, PainelFiltro } from "@/components/ui/filter-bar-painel";

/** Limites da `faixa`, obrigatórios em tempo de execução (D1). */
function limitesDaFaixa(filter: FilterConfig): LimitesFaixa {
  const { min, max } = filter;
  if (
    typeof min !== "number" ||
    typeof max !== "number" ||
    !Number.isFinite(min) ||
    !Number.isFinite(max) ||
    min > max
  ) {
    throw new Error(
      `FilterBar: o filtro "${filter.key}" é do tipo "faixa" e precisa de min e max numéricos, com min <= max.`,
    );
  }
  return { min, max };
}

const textoDe = (n: number | null) => (n === null ? "" : String(n));

// Filtro de faixa numérica, "de" e "até" (change
// catalogo-filterbar-faixa-busca-correcoes, D1): pílula com o rótulo resumido
// e o painel em portal dos selects, com dois campos numéricos. Grava
// `<key>De`/`<key>Ate` ao confirmar (Enter ou Aplicar), ao sair dos campos ou
// ao fechar o painel pelo clique fora, nunca a cada tecla; `Esc` descarta.
export function FaixaFilterControl({ filter, searchParams, setParams }: PropsControleFiltro) {
  const { open, setOpen, rect, triggerRef, panelRef, abrir } = useDropdownPortal();
  const id = useId();
  const limites = limitesDaFaixa(filter);
  const passo = filter.passo ?? 1;
  const [chaveDe, chaveAte] = chavesDaFaixa(filter);
  const urlDe = searchParams.get(chaveDe);
  const urlAte = searchParams.get(chaveAte);
  const atual = normalizarFaixa(urlDe, urlAte, limites);
  const active = atual.de !== null || atual.ate !== null;
  const rotulo = rotuloFaixa(filter.label, atual);
  const valorCompacto = resumoFaixa(atual) ?? filter.placeholder ?? "Qualquer valor";
  const [de, setDe] = useState("");
  const [ate, setAte] = useState("");
  // Edição ainda não gravada; `null` quando não há nada pendente.
  const pendente = useRef<{ de: string; ate: string } | null>(null);

  /** Grava na URL, só quando muda algo. */
  function escrever(novoDe: string, novoAte: string) {
    pendente.current = null;
    const escrita = escritaDaFaixa(filter, novoDe, novoAte, limites);
    if (escrita[chaveDe] !== (urlDe || null) || escrita[chaveAte] !== (urlAte || null))
      setParams(escrita);
  }

  /** Grava e mostra nos campos o valor normalizado (limitado e ordenado). */
  function aplicar(novoDe: string, novoAte: string) {
    const v = normalizarFaixa(novoDe, novoAte, limites);
    setDe(textoDe(v.de));
    setAte(textoDe(v.ate));
    escrever(novoDe, novoAte);
  }

  // Fechou pelo clique fora com edição pendente: grava, como ao sair do campo.
  const escreverRef = useRef(escrever);
  useEffect(() => {
    escreverRef.current = escrever;
  });
  useEffect(() => {
    if (!open && pendente.current) escreverRef.current(pendente.current.de, pendente.current.ate);
  }, [open]);

  function abrirPainel() {
    setDe(textoDe(atual.de));
    setAte(textoDe(atual.ate));
    pendente.current = null;
    abrir();
  }

  function fechar() {
    setOpen(false);
    triggerRef.current?.focus();
  }

  function onKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
    if (e.key === "Enter") {
      e.preventDefault();
      aplicar(de, ate);
      fechar();
    } else if (e.key === "Escape") {
      // O `useDropdownPortal` fecha o painel; a edição é descartada.
      pendente.current = null;
      triggerRef.current?.focus();
    }
  }

  function onBlur(e: React.FocusEvent<HTMLInputElement>) {
    // Ir de um campo ao outro, ou aos botões do painel, não grava.
    if (panelRef.current?.contains(e.relatedTarget as Node | null)) return;
    if (pendente.current) aplicar(de, ate);
  }

  function mudarDe(v: string) {
    setDe(v);
    pendente.current = { de: v, ate };
  }

  function mudarAte(v: string) {
    setAte(v);
    pendente.current = { de, ate: v };
  }

  // O que os dois campos têm em comum: número com os limites e o passo, e as
  // mesmas teclas e a mesma saída.
  const propsCampo = {
    type: "number",
    inputMode: Number.isInteger(passo) && Number.isInteger(limites.min) ? "numeric" : "decimal",
    min: limites.min,
    max: limites.max,
    step: passo,
    onKeyDown,
    onBlur,
    className: "min-h-10",
  } as const;

  return (
    <div className="relative shrink-0">
      <GatilhoFiltro
        triggerRef={triggerRef}
        icone={filter.icon}
        rotulo={rotulo}
        valorCompacto={valorCompacto}
        ariaLabel={`${filter.label}: ${valorCompacto}`}
        ativo={active}
        aberto={open}
        popup="dialog"
        type="button"
        onClick={() => (open ? setOpen(false) : abrirPainel())}
        className="focus-visible:shadow-[0_0_0_2px_var(--yellow-50),0_0_0_3px_var(--premium-ink)] focus-visible:outline-none"
      />
      <PainelFiltro
        aberto={open}
        rect={rect}
        panelRef={panelRef}
        role="dialog"
        rotulo={filter.label}
        largura={260}
        altura={200}
        className="p-3"
      >
        <div className="grid grid-cols-2 gap-3">
          <Input
            {...propsCampo}
            id={`${id}-de`}
            label="De"
            aria-label={`${filter.label}: de`}
            value={de}
            onChange={(e) => mudarDe(e.target.value)}
            placeholder={String(limites.min)}
            autoFocus
          />
          <Input
            {...propsCampo}
            id={`${id}-ate`}
            label="Até"
            aria-label={`${filter.label}: até`}
            value={ate}
            onChange={(e) => mudarAte(e.target.value)}
            placeholder={String(limites.max)}
          />
        </div>
        <div className="mt-3 flex justify-end gap-2">
          {(active || de || ate) && (
            <Button
              variant="ghost"
              size="sm"
              className="min-h-10"
              onClick={() => {
                aplicar("", "");
                fechar();
              }}
            >
              Limpar
            </Button>
          )}
          <Button
            variant="dark"
            size="sm"
            className="min-h-10"
            onClick={() => {
              aplicar(de, ate);
              fechar();
            }}
          >
            Aplicar
          </Button>
        </div>
      </PainelFiltro>
    </div>
  );
}

"use client";

import { useState, type ReactNode, type RefObject } from "react";
import { Check, Search } from "lucide-react";
import { cn } from "@/lib/utils";
import { SingleSelectItem, useDropdownPortal } from "@/components/ui/pilula";
import {
  comDependentes,
  filtrarOpcoes,
  mostrarBuscaPara,
  type FilterConfig,
  type PropsControleFiltro,
} from "@/components/ui/filter-bar-config";
import { GatilhoFiltro, PainelFiltro } from "@/components/ui/filter-bar-painel";

// Campo de busca reusado pelos dropdowns de select/multiselect (foco visível,
// teclado e tokens semânticos claro/escuro).
function OpcoesBusca({
  value,
  onChange,
  label,
}: {
  value: string;
  onChange: (v: string) => void;
  label: string;
}) {
  return (
    <div className="relative mb-1">
      <Search
        size={14}
        className="absolute top-1/2 left-2 -translate-y-1/2 text-[var(--premium-gray)]"
      />
      <input
        type="text"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        onKeyDown={(e) => e.stopPropagation()}
        placeholder="Buscar..."
        aria-label={`Buscar em ${label}`}
        autoFocus
        className="w-full rounded-[var(--r-sm)] border border-[var(--premium-mist)] bg-[var(--premium-paper)] py-[6px] pr-2 pl-7 text-[13px] text-[var(--premium-ink)] focus:border-[var(--premium-ink)] focus:shadow-[0_0_0_2px_var(--yellow-50)] focus:outline-none"
      />
    </div>
  );
}

/**
 * Painel dos filtros de seleção: a busca (listas longas), as opções e o
 * "Nenhum resultado." quando a busca não acha nada.
 */
function PainelOpcoes({
  filter,
  aberto,
  rect,
  panelRef,
  busca,
  onBusca,
  vazio,
  multiselecionavel,
  children,
}: {
  filter: FilterConfig;
  aberto: boolean;
  rect: DOMRect | null;
  panelRef: RefObject<HTMLDivElement | null>;
  busca: string;
  onBusca: (termo: string) => void;
  vazio: boolean;
  multiselecionavel?: boolean;
  children: ReactNode;
}) {
  return (
    <PainelFiltro
      aberto={aberto}
      rect={rect}
      panelRef={panelRef}
      role="listbox"
      rotulo={filter.label}
      largura={220}
      altura={320}
      multiselecionavel={multiselecionavel}
    >
      {mostrarBuscaPara(filter) && (
        <OpcoesBusca value={busca} onChange={onBusca} label={filter.label} />
      )}
      {children}
      {vazio && (
        <div className="py-4 text-center text-[13px] text-[var(--premium-gray)]">
          Nenhum resultado.
        </div>
      )}
    </PainelFiltro>
  );
}

/**
 * Estado comum dos filtros de seleção: o menu em portal, a busca e as opções
 * visíveis, e as props do gatilho e do painel. Abrir limpa a busca.
 */
function useMenuOpcoes(filter: FilterConfig) {
  const [busca, setBusca] = useState("");
  const { open, setOpen, rect, triggerRef, panelRef, abrir } = useDropdownPortal();
  const visiveis = filtrarOpcoes(filter, busca);
  return {
    busca,
    setBusca,
    setOpen,
    visiveis,
    gatilho: {
      triggerRef,
      icone: filter.icon,
      aberto: open,
      popup: "listbox" as const,
      onClick: () => {
        setBusca("");
        abrir();
      },
    },
    painel: {
      filter,
      aberto: open,
      rect,
      panelRef,
      busca,
      onBusca: setBusca,
      vazio: visiveis.length === 0,
    },
  };
}

export function SingleSelectControl({ filter, searchParams, setParams }: PropsControleFiltro) {
  const menu = useMenuOpcoes(filter);
  const value = searchParams.get(filter.key) ?? "";
  const selectedLabel = filter.options?.find((o) => o.value === value)?.label;
  const valorCompacto = (value && selectedLabel) || (filter.placeholder ?? "Todos");

  function escolher(v: string | null) {
    setParams(comDependentes(filter, v));
    menu.setBusca("");
    menu.setOpen(false);
  }

  return (
    <div className="relative shrink-0">
      <GatilhoFiltro
        {...menu.gatilho}
        rotulo={value && selectedLabel ? `${filter.label}: ${selectedLabel}` : filter.label}
        valorCompacto={valorCompacto}
        ativo={Boolean(value)}
        ariaLabel={`${filter.label}: ${valorCompacto}`}
      />
      <PainelOpcoes {...menu.painel}>
        {!menu.busca && (
          <SingleSelectItem
            checked={!value}
            label={filter.placeholder ?? "Todos"}
            onClick={() => escolher(null)}
          />
        )}
        {menu.visiveis.map((o) => (
          <SingleSelectItem
            key={o.value}
            checked={o.value === value}
            label={o.label}
            onClick={() => escolher(o.value)}
          />
        ))}
      </PainelOpcoes>
    </div>
  );
}

export function MultiSelectControl({ filter, searchParams, setParams }: PropsControleFiltro) {
  const menu = useMenuOpcoes(filter);
  const raw = searchParams.get(filter.key);
  const selected = raw ? raw.split(",").filter(Boolean) : [];
  const active = selected.length > 0;
  const rotulosEscolhidos = (filter.options ?? [])
    .filter((o) => selected.includes(o.value))
    .map((o) => o.label);
  const valorCompacto = rotulosEscolhidos.join(", ") || (filter.placeholder ?? "Todos");
  const quantas = `${selected.length} ${selected.length === 1 ? "opção" : "opções"}`;

  function toggle(optValue: string) {
    const next = selected.includes(optValue)
      ? selected.filter((v) => v !== optValue)
      : [...selected, optValue];
    setParams(comDependentes(filter, next.length ? next.join(",") : null));
  }

  return (
    <div className="relative shrink-0">
      <GatilhoFiltro
        {...menu.gatilho}
        rotulo={filter.label}
        valorCompacto={valorCompacto}
        ariaLabel={
          active
            ? `${filter.label}, ${quantas}: ${valorCompacto}`
            : `${filter.label}: ${valorCompacto}`
        }
        ativo={active}
        extra={
          // No celular, o gatilho já mostra as opções escolhidas: o contador fica só no computador.
          active && (
            <span className="min-w-[16px] rounded-full bg-[var(--premium-ink)] px-[6px] text-center text-[11px] font-bold text-[var(--premium-paper)] max-md:hidden">
              {selected.length}
            </span>
          )
        }
      />
      <PainelOpcoes {...menu.painel} multiselecionavel>
        {menu.visiveis.map((o) => {
          const checked = selected.includes(o.value);
          return (
            <button
              key={o.value}
              type="button"
              onClick={() => toggle(o.value)}
              role="option"
              aria-selected={checked}
              className="flex w-full cursor-pointer items-center gap-2 rounded-[var(--r-sm)] px-2 py-[7px] text-left text-[13px] text-[var(--premium-ink)] hover:bg-[var(--premium-bone)] focus-visible:bg-[var(--premium-bone)] focus-visible:outline-none"
            >
              <span
                className={cn(
                  "flex h-4 w-4 shrink-0 items-center justify-center rounded-[4px] border",
                  checked
                    ? "border-[var(--premium-ink)] bg-[var(--premium-ink)] text-[var(--premium-paper)]"
                    : "border-[var(--premium-mist)]",
                )}
              >
                {checked && <Check size={12} />}
              </span>
              {o.label}
            </button>
          );
        })}
      </PainelOpcoes>
    </div>
  );
}

"use client";

import type { AriaRole, ReactNode, RefObject } from "react";
import { createPortal } from "react-dom";
import { m } from "motion/react";
import { ChevronDown, type LucideIcon } from "lucide-react";
import { cn } from "@/lib/utils";
import { motionPreset } from "@/lib/motion";
import { popoverPos } from "@/lib/popover-pos";
import { chipActive, chipBase, chipIdle, dropdownPanelClass } from "@/components/ui/pilula";

/*
 * Gatilho e painel dos filtros com menu da `FilterBar` (seleção única, seleção
 * múltipla e faixa): a pílula com ícone, rótulo e chevron, e o painel em portal
 * ancorado nela pelo `useDropdownPortal`.
 */

/** Classes do gatilho no painel da barra compacta (celular): campo de 44px na largura toda. */
const GATILHO_NO_PAINEL =
  "max-md:h-11 max-md:w-full max-md:rounded-[var(--r-md)] max-md:bg-[var(--premium-white)]";

/**
 * Pílula que abre o menu de um filtro. `extra` entra entre o rótulo e o chevron.
 *
 * No celular, o gatilho fica no painel da barra compacta, com o rótulo do filtro
 * acima dele: ocupa a largura toda e mostra só o valor (`valorCompacto`). Quem
 * passa `valorCompacto` passa também `ariaLabel`, que contém os dois textos à
 * vista, o do computador e o do celular (WCAG 2.5.3, "rótulo no nome"): por
 * exemplo, "Situação: Todas". O nome não depende do tamanho da tela.
 */
export function GatilhoFiltro({
  triggerRef,
  icone: Icon,
  rotulo,
  valorCompacto,
  ativo,
  aberto,
  popup,
  onClick,
  ariaLabel,
  type,
  className,
  extra,
}: {
  triggerRef: RefObject<HTMLButtonElement | null>;
  icone?: LucideIcon;
  rotulo: string;
  valorCompacto?: string;
  ativo: boolean;
  aberto: boolean;
  popup: "listbox" | "dialog";
  onClick: () => void;
  ariaLabel?: string;
  type?: "button";
  className?: string;
  extra?: ReactNode;
}) {
  return (
    <button
      ref={triggerRef}
      type={type}
      onClick={onClick}
      aria-label={ariaLabel}
      aria-haspopup={popup}
      aria-expanded={aberto}
      className={cn(chipBase, ativo ? chipActive : chipIdle, GATILHO_NO_PAINEL, className)}
    >
      {Icon && <Icon size={14} className="shrink-0 text-[var(--premium-gray)]" />}
      {valorCompacto === undefined ? (
        <span className="max-md:min-w-0 max-md:flex-1 max-md:truncate max-md:text-left">
          {rotulo}
        </span>
      ) : (
        <>
          <span className="max-md:hidden">{rotulo}</span>
          <span className="min-w-0 flex-1 truncate text-left md:hidden">{valorCompacto}</span>
        </>
      )}
      {extra}
      <ChevronDown size={14} className="-mr-1 shrink-0 text-[var(--premium-gray)]" />
    </button>
  );
}

/** Painel do menu em portal, com a largura mínima e a altura estimada para a posição. */
export function PainelFiltro({
  aberto,
  rect,
  panelRef,
  role,
  rotulo,
  largura,
  altura,
  multiselecionavel,
  className,
  children,
}: {
  aberto: boolean;
  rect: DOMRect | null;
  panelRef: RefObject<HTMLDivElement | null>;
  role: AriaRole;
  rotulo: string;
  largura: number;
  altura: number;
  multiselecionavel?: boolean;
  className?: string;
  children: ReactNode;
}) {
  if (!aberto || !rect || typeof document === "undefined") return null;
  return createPortal(
    <m.div
      ref={panelRef}
      {...motionPreset("menu")}
      role={role}
      aria-label={rotulo}
      aria-multiselectable={multiselecionavel}
      style={popoverPos(rect, Math.max(rect.width, largura), altura)}
      className={cn(dropdownPanelClass, className)}
    >
      {children}
    </m.div>,
    document.body,
  );
}

"use client";

import type { KeyboardEvent, ReactNode, RefObject } from "react";
import { FunnelX, ListFilter } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Tooltip } from "@/components/ui/tooltip";
import type { FilterConfig } from "@/components/ui/filter-bar-config";

/*
 * Barra compacta da `FilterBar` no celular (premium-design v0.28.0, decisão do
 * dono de 19/11/2026). Abaixo de 768px (`md`), a barra vira uma linha: o
 * resumo (a aba escolhida e o texto da tela), a busca em lupa e o botão de
 * filtros, com o número de filtros ativos. O botão desce um painel que empurra
 * a lista para baixo, com as abas em cima ("Visão") e os filtros embaixo.
 *
 * Cada controle é renderizado uma vez só: no computador, os invólucros do
 * painel ficam `display: contents` e os controles voltam à linha única de
 * sempre, na ordem filtros ► contexto ► abas ► favorito (`order`).
 */

/** Rótulo de grupo e de campo do painel: eyebrow 11px, como o rótulo do `Input`. */
export const ROTULO_DO_PAINEL =
  "text-[11px] font-bold tracking-[.05em] text-[var(--premium-gray)] uppercase";

/** Linha do celular: resumo, ações da tela, busca e o botão do painel. No computador, some. */
export const LINHA_COMPACTA = "group/linha flex min-h-11 items-center gap-2 md:contents";

/** Filtros que levam o rótulo acima do campo no painel (o gatilho mostra só o valor). */
export function rotuloAcimaNoPainel(filter: FilterConfig): boolean {
  return filter.type === "select" || filter.type === "multiselect" || filter.type === "faixa";
}

/** Resumo da linha compacta: a aba escolhida, em negrito, e o texto da tela. */
export function ResumoCompacto({ aba, resumo }: { aba?: string; resumo?: string }) {
  return (
    <p
      aria-live="polite"
      className="min-w-0 flex-1 truncate text-[13px] text-[var(--premium-gray)] group-has-[[data-busca-aberta]]/linha:hidden md:hidden"
    >
      {aba && <b className="font-bold text-[var(--premium-ink)]">{aba}</b>}
      {aba && resumo ? " · " : null}
      {resumo}
    </p>
  );
}

/**
 * Botão que abre e fecha o painel: ícone de filtros e o número de filtros
 * ativos. O mesmo botão ou `Esc` fecham.
 */
export function BotaoPainelCompacto({
  botaoRef,
  aberto,
  painelId,
  ativos,
  comAbas,
  onClick,
  aoFechar,
}: {
  botaoRef: RefObject<HTMLButtonElement | null>;
  aberto: boolean;
  painelId: string;
  ativos: number;
  comAbas: boolean;
  onClick: () => void;
  aoFechar: () => void;
}) {
  const nome = comAbas ? "Visão e filtros" : "Filtros";
  return (
    <button
      ref={botaoRef}
      type="button"
      onClick={onClick}
      onKeyDown={(e) => {
        if (e.key !== "Escape" || !aberto) return;
        e.stopPropagation();
        aoFechar();
      }}
      aria-expanded={aberto}
      aria-controls={painelId}
      aria-label={
        ativos > 0 ? `${nome}, ${ativos} ${ativos === 1 ? "filtro ativo" : "filtros ativos"}` : nome
      }
      className={cn(
        "relative flex size-11 shrink-0 cursor-pointer items-center justify-center rounded-[var(--r-md)] border transition-colors focus-visible:shadow-[0_0_0_2px_var(--yellow-50)] focus-visible:outline-none md:hidden",
        aberto
          ? "border-[var(--c-emphasis)] bg-[var(--c-emphasis)] text-[var(--c-on-emphasis)]"
          : ativos > 0
            ? "border-[var(--premium-ink)] bg-[var(--premium-white)] text-[var(--premium-ink)]"
            : "border-[var(--premium-mist)] bg-[var(--premium-white)] text-[var(--premium-steel)] hover:border-[var(--premium-ink)] hover:text-[var(--premium-ink)]",
      )}
    >
      <ListFilter size={18} aria-hidden />
      {ativos > 0 && (
        <span
          aria-hidden
          className="absolute -top-[7px] -right-[7px] flex h-5 min-w-5 items-center justify-center rounded-full border-2 border-[var(--premium-paper)] bg-[var(--yellow)] px-[5px] text-[11px] leading-none font-bold text-[var(--brand-ink)]"
        >
          {ativos}
        </span>
      )}
    </button>
  );
}

/**
 * O painel que desce no celular: altura de 0 a auto em 200ms, empurrando o
 * conteúdo (não sobrepõe), sem animação com `prefers-reduced-motion`. Fechado,
 * fica `invisible`, fora do Tab e do leitor de tela. `Esc` dentro dele fecha e
 * devolve o foco ao botão (o `Esc` de um menu de filtro aberto fecha só o menu).
 * No computador, os três invólucros ficam `display: contents`.
 */
export function PainelCompacto({
  id,
  painelRef,
  aberto,
  aoFechar,
  rotuloFechar,
  children,
}: {
  id: string;
  painelRef: RefObject<HTMLDivElement | null>;
  aberto: boolean;
  aoFechar: () => void;
  rotuloFechar: string;
  children: ReactNode;
}) {
  function onKeyDown(e: KeyboardEvent<HTMLDivElement>) {
    if (e.key !== "Escape" || !aberto) return;
    const alvo = e.target;
    // Menus dos filtros vêm em portal: o evento do React chega aqui, o DOM não.
    if (!(alvo instanceof Element) || !e.currentTarget.contains(alvo)) return;
    if (alvo.closest('[aria-expanded="true"]')) return;
    e.stopPropagation();
    aoFechar();
  }

  return (
    <div
      id={id}
      ref={painelRef}
      onKeyDown={onKeyDown}
      className={cn(
        "grid transition-[grid-template-rows,opacity,visibility] duration-200 ease-[var(--ease)] motion-reduce:transition-none md:visible md:contents",
        aberto ? "visible grid-rows-[1fr] opacity-100" : "invisible grid-rows-[0fr] opacity-0",
      )}
    >
      <div className="min-h-0 overflow-hidden md:contents">
        <div className="mt-2.5 rounded-[var(--r-lg)] border border-[var(--premium-mist)] bg-[var(--premium-white)] shadow-[var(--sh-sm)] md:contents">
          {children}
          <div className="border-t border-[var(--premium-mist)] px-4 py-3 md:hidden">
            <Button type="button" variant="dark" size="sm" className="w-full" onClick={aoFechar}>
              {rotuloFechar}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * "Limpar filtros", um botão só: no computador, o redondo amarelo com o funil
 * no fim dos filtros; no celular, o texto "Limpar filtros" no cabeçalho do grupo
 * Filtros do painel.
 */
export function LimparFiltros({ onClick }: { onClick: () => void }) {
  return (
    <Tooltip
      label="Limpar filtros"
      side="bottom"
      className="shrink-0 max-md:absolute max-md:top-1.5 max-md:right-2.5"
      bubbleClassName="max-md:hidden"
    >
      <button
        type="button"
        onClick={onClick}
        aria-label="Limpar filtros"
        className={cn(
          "flex shrink-0 cursor-pointer items-center justify-center transition-colors focus-visible:shadow-[0_0_0_2px_var(--yellow-50)] focus-visible:outline-none",
          "md:h-9 md:w-9 md:rounded-full md:bg-[var(--yellow)] md:text-[var(--premium-black)] md:shadow-[var(--sh-gold)] md:hover:bg-[var(--gold)] md:active:bg-[var(--amber)]",
          "max-md:min-h-10 max-md:gap-1.5 max-md:rounded-[var(--r-sm)] max-md:px-1.5 max-md:text-[12.5px] max-md:font-medium max-md:text-[var(--premium-ink)] max-md:underline max-md:underline-offset-2",
        )}
      >
        <FunnelX size={16} strokeWidth={2.5} aria-hidden />
        <span aria-hidden className="md:hidden">
          Limpar filtros
        </span>
      </button>
    </Tooltip>
  );
}
